		<!-- wp:group {"className":"wcr-section-intro","layout":{"type":"flex","flexWrap":"wrap","justifyContent":"space-between","verticalAlignment":"bottom"}} --><div class="wp-block-group wcr-section-intro"><!-- wp:group {"layout":{"type":"default"}} --><div class="wp-block-group"><!-- wp:paragraph {"className":"wcr-kicker"} --><p class="wcr-kicker">FROM PURCHASE TO PROOF</p><!-- /wp:paragraph --><!-- wp:heading {"className":"wcr-section-title"} --><h2 class="wp-block-heading wcr-section-title">A complete review<br><em>workflow.</em></h2><!-- /wp:heading --></div><!-- /wp:group --><!-- wp:paragraph {"className":"wcr-section-lede"} --><p class="wcr-section-lede">Collect, moderate, display, and follow up from one WooCommerce-focused plugin.</p><!-- /wp:paragraph --></div><!-- /wp:group -->
