			<!-- wp:group {"tagName":"article","className":"wcr-workflow-card","layout":{"type":"default"}} --><article class="wp-block-group wcr-workflow-card"><!-- wp:paragraph {"className":"wcr-step"} --><p class="wcr-step">01 · COLLECT</p><!-- /wp:paragraph --><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">A familiar review form, upgraded</h3><!-- /wp:heading --><!-- wp:paragraph --><p>Customers can write and rate as usual, then record a video, upload an existing clip, or attach product photos—all without leaving the product page.</p><!-- /wp:paragraph --></article><!-- /wp:group -->
			<!-- wp:group {"tagName":"article","className":"wcr-workflow-card","layout":{"type":"default"}} --><article class="wp-block-group wcr-workflow-card"><!-- wp:paragraph {"className":"wcr-step"} --><p class="wcr-step">02 · CONTROL</p><!-- /wp:paragraph --><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">Privacy and moderation built in</h3><!-- /wp:heading --><!-- wp:paragraph --><p>Enable capture methods independently, require video when needed, request consent with editable privacy text, and moderate media from a dedicated admin screen.</p><!-- /wp:paragraph --></article><!-- /wp:group -->
			<!-- wp:group {"tagName":"article","className":"wcr-workflow-card","layout":{"type":"default"}} --><article class="wp-block-group wcr-workflow-card"><!-- wp:paragraph {"className":"wcr-step"} --><p class="wcr-step">03 · DISPLAY</p><!-- /wp:paragraph --><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">Visual proof that is easy to explore</h3><!-- /wp:heading --><!-- wp:paragraph --><p>Approved photos and videos appear with the review and open in a responsive lightbox. Supported review media is also included in product structured data.</p><!-- /wp:paragraph --></article><!-- /wp:group -->
